set -a; . /root/.env 2>/dev/null; set +a
BASE="https://xprime17.app.n8n.cloud/api/v1"
curl -s -H "X-N8N-API-KEY: $N8N_API_KEY" "$BASE/executions/22021?includeData=true" \
 | python3 -c '
import sys,json
d=json.load(sys.stdin)
run=d.get("data",{}).get("resultData",{}).get("runData",{})
print("Per-node: runs / total output items")
for node,runs in run.items():
    total=0
    for r in runs:
        try: total+=len(r["data"]["main"][0])
        except: pass
    print(f"  {node:42s} runs={len(runs):3d} items={total}")
err=d.get("data",{}).get("resultData",{}).get("error")
if err: print("EXEC ERROR:",str(err)[:300])
# program distribution across Classify Lead all runs
prog={}
for r in run.get("Classify Lead",[]):
    try:
        for it in r["data"]["main"][0]:
            p=it["json"].get("lead_program") or it["json"].get("program") or "?"
            prog[p]=prog.get(p,0)+1
    except: pass
print("Classify program distribution:",prog)
'
